9	/**
10	 * Rejects a create-owner request whose E.164 telephone is already used by another owner.
11	 * Runs after {@link NormalizeOwnerTelephone} (so the body carries the E.164 value) and
12	 * before {@link BuildOwner}, comparing E.164 values against every existing owner. A
13	 * collision is rejected 409 via {@link DuplicateTelephoneException}.
14	 */
15	public class RejectDuplicateTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(E164Telephone.normalizeOrNull(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(
23	                        "Telephone is already used by another owner");
24	            }
25	        }
26	    }
27	}
